SELECT CASE WHEN cost >= 77 THEN 'high' WHEN cost >= 44 THEN 'mid' ELSE 'low' END AS cost_bucket, CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END AS shipped_cohort, carrier, ROUND(STDDEV(cost), 2) AS stddev_cost, COUNT(cost) AS cost_count FROM shipments WHERE delivered_date >= '2025-10-01' AND status = 'IN_TRANSIT' AND carrier != 'UPS' GROUP BY CASE WHEN cost >= 77 THEN 'high' WHEN cost >= 44 THEN 'mid' ELSE 'low' END, CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END, carrier HAVING stddev_cost > 60 ORDER BY stddev_cost, cost_bucket, shipped_cohort, carrier LIMIT 3
